            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;rophante-Mythique.html&quot; title=&quot;Le hi&#233;rophante mythique&quot;&gt;hi&#233;rophante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Hi&#233;rophante-Mythique.html&quot; title=&quot;Aptitudes de voie du hi&#233;rophante mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;chal-Mythique.html&quot; title=&quot;Le mar&#233;chal mythique&quot;&gt;mar&#233;chal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Mar&#233;chal-Mythique.html&quot; title=&quot;Aptitudes de voie du mar&#233;chal mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Protecteur-Mythique.html&quot; title=&quot;Le protecteur mythique&quot;&gt;protecteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;Aptitudes de voie universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Des-Enfants-Divins-Mythiques.html&quot; title=&quot;Aptitudes de voie des enfants divins mythiques&quot;&gt;Aptitudes de voie des enfants divins&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;Options de personnage mythiques&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;Les dons mythiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;tableau&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton4&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;4&#39;);&quot; onmouseout=&quot;outButton(&#39;4&#39;);&quot; onclick=&quot;expandMenu(&#39;4&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;La table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html#STATMONSTRESMYTHIQUEPARFP&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;Statistiques des monstres par FP&lt;/a&gt;&quot; liste les statistiques approximatives des monstres allant jusqu’au FP 30 (les informations pour les &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de 1 &#224; 20 sont identiques &#224; celles du Bestiaire). Ces valeurs sont des indications g&#233;n&#233;rales. La plupart des monstres excellent dans un seul de ces domaines (g&#233;n&#233;ralement dans le nombre de d&#233;g&#226;ts inflig&#233;s) mais sont moins performants dans un ou deux autres domaines, ce qui permet de les &#233;quilibrer. Par exemple, un monstre pourrait infliger plus de d&#233;g&#226;ts que ce qui est indiqu&#233; dans la table mais il aurait une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et un nombre de points de vie moindres. Les entr&#233;es de la table se pr&#233;sentent comme suit.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;FP.&lt;/b&gt; Il s’agit du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; moyen du monstre. Il peut changer &#224; mesure que la cr&#233;ation progresse.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Points de vie.&lt;/b&gt; Il s’agit du total de points de vie moyen du monstre. Une cr&#233;ature ayant une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; particuli&#232;rement &#233;lev&#233;e, des bonus de sauvegarde particuli&#232;rement importants ou un certain nombre de r&#233;sistances pourraient avoir moins de points de vie. Les ext&#233;rieurs et les cr&#233;atures artificielles ont g&#233;n&#233;ralement un total de points de vie inf&#233;rieur.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Classe d’armure.&lt;/b&gt; Il s’agit de la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; moyenne d’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233;. Quand vient le moment de cr&#233;er les protections de la cr&#233;ature, gardez bien ce nombre en t&#234;te. Les cr&#233;atures dont le total de points de vie est sup&#233;rieur &#224; la moyenne ont g&#233;n&#233;ralement une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; moindre pour compenser.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Attaque sup&#233;rieure.&lt;/b&gt; Il s’agit du bonus d’attaque moyen d’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233;, qui se bat principalement au corps &#224; corps ou &#224; distance. Les cr&#233;atures infligeant des d&#233;g&#226;ts sup&#233;rieurs &#224; la moyenne normale ont g&#233;n&#233;ralement une valeur d’attaque moindre pour compenser.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Attaque inf&#233;rieure.&lt;/b&gt; Il s’agit du bonus d’attaque total moyen d’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233; qui ne recourt pas aux attaques au corps &#224; corps ou &#224; distance pour infliger des d&#233;g&#226;ts, ce qui inclut la plupart des cr&#233;atures qui se battent principalement &#224; l’aide de sorts et de pouvoirs magiques.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;g&#226;ts moyens.&lt;/b&gt; Il s’agit du nombre moyen de d&#233;g&#226;ts qu’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233; inflige quand elle r&#233;ussit toutes ses attaques. Pour d&#233;terminer les d&#233;g&#226;ts moyens d’une cr&#233;ature, ajoutez la valeur moyenne de tous ses d&#233;s de d&#233;g&#226;ts au modificateur de d&#233;g&#226;ts de chaque attaque. Une cr&#233;ature qui se bat avec des armes de corps &#224; corps devrait infliger un nombre de d&#233;g&#226;ts moyens situ&#233; entre les d&#233;g&#226;ts sup&#233;rieurs et les d&#233;g&#226;ts inf&#233;rieurs. Une cr&#233;ature ayant des bonus d’attaque sup&#233;rieurs &#224; la normale inflige souvent moins de d&#233;g&#226;ts et une cr&#233;ature ayant des bonus d’attaque inf&#233;rieurs &#224; la normale inflige souvent plus de d&#233;g&#226;ts.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du pouvoir principal.&lt;/b&gt; Il s’agit du degr&#233; de difficult&#233; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;) moyen de tous les sorts, pouvoirs magiques et pouvoirs sp&#233;ciaux (comme les armes de souffle) que poss&#232;de une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233; qui se repose principalement sur de telles attaques en combat. Si elle poss&#232;de un pouvoir particuli&#232;rement puissant, il peut avoir un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; inf&#233;rieur pour compenser.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du pouvoir secondaire.&lt;/b&gt; Il s’agit du degr&#233; de difficult&#233; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt;) moyen de tous les sorts et pouvoirs sp&#233;ciaux que poss&#232;de une cr&#233;ature du FP donn&#233; ne comptant pas sur de telles attaques en combat. En g&#233;n&#233;ral, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; d’un pouvoir ne devrait pas &#234;tre inf&#233;rieur &#224; ce nombre.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Bon JdS.&lt;/b&gt; Il s’agit du bonus de sauvegarde moyen d’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233;, si le jet de sauvegarde fait partie des bons jets de la cr&#233;ature.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Mauvais JdS.&lt;/b&gt; Il s’agit du bonus de sauvegarde moyen d’une cr&#233;ature du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; donn&#233;, si le jet de sauvegarde fait partie des mauvais jets de la cr&#233;ature.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;80%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;STATMONSTRESMYTHIQUEPARFP&quot; href=&quot;#STATMONSTRESMYTHIQUEPARFP&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Statistiques des monstres par FP&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;FP&lt;/td&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;pv&lt;/td&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;CA&lt;/td&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;avecsoustitre&quot;&gt;Attaque&lt;/td&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;avecsoustitre&quot;&gt;D&#233;g&#226;ts moyens&lt;/td&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;avecsoustitre&quot;&gt;DD du pouvoir&lt;/td&gt;&lt;td COLSPAN=&quot;2&quot; CLASS=&quot;avecsoustitre&quot;&gt;JdS&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;soustitre&quot;&gt;&lt;td&gt;sup&#233;rieure&lt;/td&gt;&lt;td&gt;inf&#233;rieure&lt;/td&gt;&lt;